/* Les d'Amours ❤️ — single-page PWA. Local-first, optional Supabase sync. */
const CFG=window.SUPABASE_CONFIG||{};
const hasSupabase=!!(window.supabase&&CFG.url&&CFG.publishableKey&&!CFG.url.includes('TON-PROJET'));
const sb=hasSupabase?window.supabase.createClient(CFG.url,CFG.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}):null;
const KEY='les-damours-state-v1', DEVICE='les-damours-device-v1';
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const todayISO=()=>{const d=new Date();return localDate(d)};
const localDate=d=>{const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`};
const parseDate=s=>{const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d)};
const addDays=(s,n)=>{const d=parseDate(s);d.setDate(d.getDate()+n);return localDate(d)};
const startWeek=s=>{const d=parseDate(s);const day=d.getDay();const diff=day===0?-6:1-day;d.setDate(d.getDate()+diff);return localDate(d)};
const fmtDate=(s,opt={day:'numeric',month:'short'})=>parseDate(s).toLocaleDateString('fr-FR',opt);
const weekDays=s=>Array.from({length:7},(_,i)=>addDays(s,i));
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const safeUrl=s=>{try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:null}catch{return null}};
const defaultState=()=>({
  version:1, profile:{me:'Fanny',him:'Thomas'}, weekStart:startWeek(todayISO()),
  events:[], birthdays:[], menus:[], tasks:[], shopping:{items:[],staples:[]}, expenses:[], reimbursements:[],
  settings:{icons:[['🩺','Médecin'],['🦷','Dentiste'],['🚗','Garage'],['💼','Travail'],['🏠','Maison'],['💇','Coiffeur'],['🐾','Vétérinaire'],['🛒','Courses'],['🍿','Sortie'],['✈️','Voyage'],['🍽️','Restaurant'],['💪','Sport'],['📌','Autre']],
  taskMoods:{me:{name:'Doux',enabled:true,messages:['Et une chose de moins à gérer ❤️','Petit pas, grande victoire 🌸','Bravo, tu avances ! ✨']},him:{name:'Helldivers',enabled:true,messages:['MISSION ACCOMPLIE. SUPER-TERRE VOUS REMERCIE. 🫡','DÉMOCRATIE DISTRIBUÉE. 🪖','OBJECTIF ÉLIMINÉ. RETOUR AU FRONT. 💥','+1 contribution à la démocratie. ⭐']}}}
});
let state=load(); let currentView='home'; let weekStart=state.weekStart||startWeek(todayISO()); let taskFilter='all',shopFilter='all';
let sync={online:false,connected:false,household:null,authUser:null,channel:null};
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(!x)return defaultState();const d=defaultState();return {...d,...x,birthdays:x.birthdays||[],settings:{...d.settings,...x.settings,taskMoods:{...d.settings.taskMoods,...x.settings?.taskMoods}}}}catch{return defaultState()}}
function saveLocal(){state.weekStart=weekStart;localStorage.setItem(KEY,JSON.stringify(state))}
function save(){saveLocal();renderAll();queueSync()}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),2600)}
function celebrate(person){const mood=state.settings.taskMoods?.[person];if(!mood?.enabled||!mood.messages?.length)return;const msg=mood.messages[Math.floor(Math.random()*mood.messages.length)];const el=document.createElement('div');el.className='celebrate';el.innerHTML=`<div class="big">${person==='him'?'🪖':'🌸'}</div><strong>${esc(msg)}</strong>`;document.body.appendChild(el);setTimeout(()=>el.remove(),2400)}
function ownerClass(owner){return owner==='me'?'me':owner==='him'?'him':'both'}
function ownerName(owner){return owner==='me'?state.profile.me:owner==='him'?state.profile.him:'Nous deux'}
function eventOccursOnDate(e,date){const end=e.endDate||e.date;return !!e.date&&date>=e.date&&date<=end}
function eventTimeLabel(e,date){const endDate=e.endDate||e.date;if(endDate===e.date&&e.endTime)return e.time+'–'+e.endTime;if(date===e.date&&e.endDate&&e.endDate!==e.date)return e.time+' →';if(date===endDate&&e.endDate&&e.endDate!==e.date)return e.endTime?'→ '+e.endTime:'Toute la journée';if(e.endDate&&e.endDate!==e.date)return 'Toute la journée';return e.time||'Toute la journée'}
function birthdayOccursOnDate(b,date){return !!b.date&&b.date.slice(5)===date.slice(5)}
function birthdayDateLabel(b){return b.date?fmtDate('2000-'+b.date.slice(5),{day:'numeric',month:'long'}):''}
function iconFor(type){return state.settings.icons.find(x=>x[1]===type)?.[0]||'📌'}
function renderAll(){renderHome();renderWeek();renderTasks();renderShopping();renderExpenses();renderSettings();document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${currentView}`));document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView))}
function renderHome(){const date=todayISO();const ev=state.events.filter(e=>eventOccursOnDate(e,date)).sort((a,b)=>(a.time||'').localeCompare(b.time||''));const birthdays=state.birthdays.filter(b=>birthdayOccursOnDate(b,date));const menus=state.menus.filter(m=>m.date===date).sort((a,b)=>({matin:0,midi:1,soir:2}[a.meal]-({matin:0,midi:1,soir:2}[b.meal])));const tasks=state.tasks.filter(t=>t.date===date&&!t.done);const bal=balance();document.getElementById('view-home').innerHTML=`<div class="eyebrow">${fmtDate(date,{weekday:'long',day:'numeric',month:'long'})}</div><h1 class="page-title">Aujourd'hui <span class="script">❤️</span></h1><div class="row wrap" style="margin:12px 0"><button class="btn primary" data-action="add">＋ Ajouter</button><button class="btn" data-action="week">Voir la semaine</button><span class="muted" style="font-size:12px;margin-left:auto"><span class="sync-dot ${sync.connected?'ok':'off'}"></span>${sync.connected?'Synchronisé':'Local / non connecté'}</span></div><div class="summary-grid"><button class="card summary-card summary-link" data-view="tasks"><div class="muted">À faire</div><div class="summary-number">${tasks.length}</div><small class="muted">tâche${tasks.length>1?'s':''} aujourd'hui</small></button><button class="card summary-card summary-link" data-view="shopping"><div class="muted">Courses</div><div class="summary-number">${state.shopping.items.filter(i=>!i.done).length}</div><small class="muted">article${state.shopping.items.filter(i=>!i.done).length>1?'s':''}</small></button></div><div class="section-head"><h2>La journée</h2></div><div class="today-list">${birthdays.map(birthdayHTML).join('')}${ev.map(eventHTML).join('')}${menus.map(menuHTML).join('')}${tasks.map(taskHTML).join('')}${!ev.length&&!menus.length&&!tasks.length?'<div class="card empty">Rien de prévu pour le moment 🌿<br><small>Profitez de votre calme.</small></div>':''}</div><div class="section-head"><h2>💰 Notre équilibre</h2><button class="btn small" data-view="expenses">Voir</button></div><div class="expense-balance card"><div class="muted">${balanceText(bal)}</div><div class="balance-amount ${bal===0?'balance-zero':bal>0?'positive':'negative'}">${money(Math.abs(bal))}</div><small class="muted">${bal===0?'Tout est équilibré ❤️':'solde actuel'}</small></div>`}
function eventHTML(e){return `<button class="list-item" style="text-align:left;width:100%" data-edit-event="${e.id}"><span class="dot ${ownerClass(e.owner)}"></span><div class="item-main"><strong>${esc(eventTimeLabel(e,todayISO()))} · ${esc(e.title)} ${esc(e.icon||iconFor(e.category))}</strong><small>${e.address?`📍 ${esc(e.address)}`:'Rendez-vous'}${e.endDate&&e.endDate!==e.date?` · ${fmtDate(e.date)} → ${fmtDate(e.endDate)}`:''} ${e.notes?'· '+esc(e.notes):''}</small></div><span class="pill ${ownerClass(e.owner)}">${esc(ownerName(e.owner))}</span></button>`}
function birthdayHTML(b){return `<button class="list-item birthday-item" style="text-align:left;width:100%" data-birthday-edit="${b.id}"><span class="dot birthday"></span><div class="item-main"><strong>🎂 ${esc(b.name)}</strong><small>Anniversaire · ${esc(birthdayDateLabel(b))}</small></div><span class="pill birthday">🎂</span></button>`}
function menuHTML(m){const link=safeUrl(m.link);return `<button class="list-item" style="text-align:left;width:100%" data-edit-menu="${m.id}"><span class="dot menu"></span><div class="item-main"><strong>🍽️ ${esc(cap(m.meal))} · ${esc(m.title)}</strong><small>${link?'🔗 recette disponible':'Menu'}</small></div></button>`}
function taskHTML(t){return `<div class="list-item task ${t.done?'done':''}"><button class="task-check ${t.done?'checked':''}" data-toggle-task="${t.id}">${t.done?'✓':''}</button><div class="item-main"><strong class="task-title">${esc(t.title)}</strong><small>${esc(ownerName(t.owner))} · ${esc(priorityLabel(t.priority))}${t.recurring?' · 🔁':''}</small></div><span class="priority ${t.priority}">${esc(priorityShort(t.priority))}</span><button class="btn small" data-edit-task="${t.id}">⋯</button></div>`}
function renderWeek(){
  const days=weekDays(weekStart);
  const html='<div class="row between"><div><div class="eyebrow">Calendrier</div><h1 class="page-title">Notre semaine</h1></div><button class="btn small" data-action="today">Aujourd\'hui</button></div>'
    +'<div class="calendar-nav"><button class="circle-btn" data-action="prev-week">‹</button><strong>Semaine du '+fmtDate(days[0])+' au '+fmtDate(days[6])+'</strong><button class="circle-btn" data-action="next-week">›</button></div>'
    +'<div class="filters"><button class="filter active" data-weekfilter="all">Tout</button><button class="filter" data-weekfilter="me">'+esc(state.profile.me)+'</button><button class="filter" data-weekfilter="him">'+esc(state.profile.him)+'</button><button class="filter" data-weekfilter="both">Nous deux</button><button class="filter" data-weekfilter="menu">Menus</button></div>'
    +'<div class="week-grid">'+days.map(d=>{
      const birthdays=state.birthdays.filter(b=>birthdayOccursOnDate(b,d));
      const events=state.events.filter(e=>eventOccursOnDate(e,d)).sort((a,b)=>(a.time||'').localeCompare(b.time||''));
      const menus=state.menus.filter(m=>m.date===d);
      return '<section class="day-col '+(d===todayISO()?'today-day':'')+'"><div class="day-head"><div>'+parseDate(d).toLocaleDateString('fr-FR',{weekday:'long'})+'</div><strong>'+parseDate(d).getDate()+'</strong></div><button class="add-day" data-add-date="'+d+'">＋ Ajouter</button>'
        +birthdays.map(b=>'<button class="event-card birthday" data-birthday-edit="'+b.id+'"><span class="time">🎂</span><strong>'+esc(b.name)+'</strong><small>Anniversaire</small></button>').join('')
        +events.map(e=>'<button class="event-card '+ownerClass(e.owner)+'" data-edit-event="'+e.id+'"><span class="time">'+esc(eventTimeLabel(e,d))+'</span> <span class="event-icon">'+esc(e.icon||iconFor(e.category))+'</span><strong>'+esc(e.title)+'</strong>'+(e.endDate&&e.endDate!==e.date?'<small>'+fmtDate(e.date)+' → '+fmtDate(e.endDate)+'</small>':'')+'</button>').join('')
        +menus.map(m=>'<button class="event-card menu" data-edit-menu="'+m.id+'"><span>'+esc(cap(m.meal))+'</span><strong>🍽️ '+esc(m.title)+'</strong></button>').join('')
        +(!birthdays.length&&!events.length&&!menus.length?'<div class="day-empty">Rien de prévu</div>':'')+'</section>';
    }).join('')+'</div>';
  document.getElementById('view-week').innerHTML=html;
}
function renderTasks(){const date=todayISO();let tasks=state.tasks.filter(t=>t.date===date);if(taskFilter!=='all')tasks=tasks.filter(t=>t.owner===taskFilter||t.priority===taskFilter);document.getElementById('view-tasks').innerHTML=`<div class="eyebrow">À faire ensemble</div><h1 class="page-title">To-do <span class="script">✨</span></h1><div class="row wrap" style="margin:12px 0"><button class="btn primary" data-action="add-task">＋ Tâche</button></div><div class="filters"><button class="filter ${taskFilter==='all'?'active':''}" data-taskfilter="all">Toutes</button><button class="filter ${taskFilter==='me'?'active':''}" data-taskfilter="me">${esc(state.profile.me)}</button><button class="filter ${taskFilter==='him'?'active':''}" data-taskfilter="him">${esc(state.profile.him)}</button><button class="filter ${taskFilter==='urgent'?'active':''}" data-taskfilter="urgent">Urgent</button><button class="filter ${taskFilter==='chill'?'active':''}" data-taskfilter="chill">Si tu as le temps</button></div><div class="section-head"><h2>Aujourd'hui</h2><span class="muted">${tasks.filter(t=>!t.done).length} restantes</span></div><div class="today-list">${tasks.sort((a,b)=>priorityRank(a.priority)-priorityRank(b.priority)).map(taskHTML).join('')||'<div class="card empty">Aucune tâche ici 🌿</div>'}</div><div class="section-head"><h2>À venir</h2></div><div class="today-list">${state.tasks.filter(t=>t.date>date&&!t.done).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5).map(t=>`<div class="list-item"><span class="dot ${ownerClass(t.owner)}"></span><div class="item-main"><strong>${esc(t.title)}</strong><small>${fmtDate(t.date)} · ${priorityLabel(t.priority)}</small></div></div>`).join('')||'<div class="muted">Rien de prévu plus tard.</div>'}</div>`}
function renderShopping(){const groups=['Protéines','Desserts','Légumes','Fruits','Petit-déj','Boissons','Goûter','Fromage','Féculents','Apéro','Maison','Autre'];let items=state.shopping.items;if(shopFilter==='open')items=items.filter(i=>!i.done);if(shopFilter!=='all'&&shopFilter!=='open')items=items.filter(i=>i.category===shopFilter);const cats=groups.filter(g=>items.some(i=>i.category===g));document.getElementById('view-shopping').innerHTML=`<div class="eyebrow">Liste partagée</div><h1 class="page-title">Courses 🛒</h1><div class="row wrap" style="margin:12px 0"><button class="btn primary" data-action="add-shopping">＋ Article</button><button class="btn" data-action="staples">Mes habituels</button><button class="btn" data-action="suggestions">Suggestions</button></div><div class="filters"><button class="filter ${shopFilter==='all'?'active':''}" data-shopfilter="all">Tout</button><button class="filter ${shopFilter==='open'?'active':''}" data-shopfilter="open">À acheter</button>${groups.slice(0,6).map(g=>`<button class="filter ${shopFilter===g?'active':''}" data-shopfilter="${esc(g)}">${esc(g)}</button>`).join('')}</div><div class="card" style="margin-top:12px">${cats.length?cats.map(cat=>`<div class="category-head">${cat}</div>${items.filter(i=>i.category===cat).map(shopHTML).join('')}`).join(''):'<div class="empty">La liste est vide 🌸<br><small>Ajoutez un article ou utilisez vos habituels.</small></div>'}</div>`}
function shopHTML(i){return `<div class="shop-item ${i.done?'done':''}"><button class="mini-check ${i.done?'checked':''}" data-toggle-shop="${i.id}">${i.done?'✓':''}</button><div class="item-main"><strong class="shop-name ${i.owner==='me'?'owner-font-me':i.owner==='him'?'owner-font-him':''}">${esc(i.name)}</strong><small>${esc(i.category||'Autre')}${i.qty?' · '+esc(i.qty):''}</small></div><button class="btn small" data-edit-shop="${i.id}">⋯</button></div>`}
function renderExpenses(){const bal=balance();document.getElementById('view-expenses').innerHTML=`<div class="eyebrow">À deux</div><h1 class="page-title">Dépenses 💰</h1><div class="expense-balance card"><div class="muted">${balanceText(bal)}</div><div class="balance-amount ${bal===0?'balance-zero':bal>0?'positive':'negative'}">${money(Math.abs(bal))}</div><small class="muted">${bal===0?'Tout est équilibré ❤️':'hors remboursements déjà saisis'}</small></div><div class="row wrap" style="margin:12px 0"><button class="btn primary" data-action="add-expense">＋ Dépense</button>${bal!==0?`<button class="btn" data-action="reimburse">Rembourser ${money(Math.abs(bal))}</button>`:''}</div><div class="section-head"><h2>Historique</h2></div><div class="card">${state.expenses.sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<div class="expense-row"><div><strong>${esc(e.label)}</strong><div class="muted" style="font-size:12px">${fmtDate(e.date)} · ${e.payer==='me'?'Fanny':'Thomas'} → ${e.mode==='custom'?esc(e.details||'répartition'):e.mode==='both'?'nous deux':e.mode==='me'?'Fanny':'Thomas'}</div></div><strong>${money(e.amount)}</strong></div>`).join('')||'<div class="empty">Aucune dépense enregistrée.</div>'}</div><div class="section-head"><h2>Remboursements</h2></div><div class="card">${state.reimbursements.sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<div class="expense-row"><div><strong>↗️ ${esc(r.from==='me'?'Fanny':'Thomas')} → ${esc(r.to==='me'?'Fanny':'Thomas')}</strong><div class="muted" style="font-size:12px">${fmtDate(r.date)}${r.note?' · '+esc(r.note):''}</div></div><strong>${money(r.amount)}</strong></div>`).join('')||'<div class="empty">Aucun remboursement.</div>'}</div>`}
function renderSettings(){document.getElementById('view-settings').innerHTML=`<div class="eyebrow">Personnalisation</div><h1 class="page-title">Réglages ⚙️</h1><div class="card"><div class="settings-row"><div><strong>Identité</strong><div class="muted">Typographies des deux personnes</div></div><button class="btn small" data-action="profiles">Modifier</button></div><div class="settings-row"><div><strong>Catégories de rendez-vous</strong><div class="muted">Icônes personnalisables</div></div><button class="btn small" data-action="categories">Gérer</button></div><div class="settings-row"><div><strong>Anniversaires</strong><div class="muted">Chaque année automatiquement 🎂</div></div><button class="btn small" data-action="birthdays">Gérer</button></div><div class="settings-row"><div><strong>Messages motivants</strong><div class="muted">Moods activables et messages aléatoires</div></div><button class="btn small" data-action="moods">Gérer</button></div><div class="settings-row"><div><strong>Sauvegarde</strong><div class="muted">Exporter une copie de toutes vos données</div></div><button class="btn small" data-action="export">Exporter</button></div><div class="settings-row"><div><strong>Restaurer</strong><div class="muted">Importer une sauvegarde JSON</div></div><button class="btn small" data-action="import">Importer</button></div></div><div class="section-head"><h2>Synchronisation</h2></div><div class="card"><div class="notice"><strong>${sync.connected?'☁️ Synchronisation active':'📱 Mode local'}</strong><br>${hasSupabase?'Connecte les deux téléphones au même espace pour partager les données.':'Cette version fonctionne déjà localement. Pour synchroniser deux téléphones, configure Supabase gratuitement puis renseigne config.js.'}</div>${hasSupabase?`<div class="settings-row"><div><strong>Compte</strong><div class="muted">${sync.authUser?esc(sync.authUser.email||'Compte connecté'):'Non connecté'}</div></div><button class="btn small" data-action="auth">${sync.authUser?'Compte':'Se connecter'}</button></div>${sync.authUser&&!sync.household?`<div class="settings-row"><div><strong>Foyer partagé</strong><div class="muted">Crée le foyer sur un téléphone puis rejoins-le avec le code sur l’autre.</div></div><button class="btn small" data-action="household">Configurer</button></div>`:''}${sync.household?`<div class="settings-row"><div><strong>Code du foyer</strong><div class="muted">À utiliser sur le deuxième téléphone</div></div><span class="code">${esc(sync.household.code)}</span></div>`:''}`:''}</div><p class="muted" style="font-size:11px;margin:14px 4px">Les données restent à vous. Exportez régulièrement une sauvegarde, surtout avant une grosse modification.</p>`}
function cap(s){return s?String(s).charAt(0).toUpperCase()+String(s).slice(1):''}
function money(n){return new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(Math.abs(Number(n)||0))}
function balance(){let b=0;for(const e of state.expenses){const a=Number(e.amount)||0;if(e.mode==='both'){b+=e.payer==='me'?a/2:-a/2}else if(e.mode==='me'){if(e.payer==='him')b-=a}else if(e.mode==='him'){if(e.payer==='me')b+=a}else if(e.mode==='custom'){const f=Number(e.meShare)||0;const t=Number(e.himShare)||0;b+=(e.payer==='me'?a-f:-(a-t))}}for(const r of state.reimbursements){if(r.from==='him'&&r.to==='me')b-=Number(r.amount)||0;if(r.from==='me'&&r.to==='him')b+=Number(r.amount)||0}return Math.round(b*100)/100}
function balanceText(b){if(b===0)return 'Vous êtes à jour';return b>0?'Thomas doit à Fanny':'Fanny doit à Thomas'}
function priorityRank(p){return ({urgent:0,important:1,normal:2,chill:3}[p]??2)}function priorityLabel(p){return ({urgent:'Urgent',important:'Important',normal:'À faire',chill:'Si tu as le temps'}[p]||'À faire')}function priorityShort(p){return ({urgent:'Urgent',important:'Important',normal:'Normal',chill:'Chill'}[p]||'Normal')}
function showModal(title,body){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" data-close-modal><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="close" data-close-modal>×</button></div>${body}</div></div>`}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function addModal(date=todayISO()){showModal('Ajouter',`<div class="summary-grid"><button class="card" data-modal="event" data-add-date="${date}"><strong>📅 Rendez-vous</strong><small class="muted">Une date et une heure précises</small></button><button class="card" data-modal="menu"><strong>🍽️ Menu</strong><small class="muted">Matin, midi ou soir</small></button><button class="card" data-modal="task"><strong>☑️ Tâche</strong><small class="muted">Priorité + récurrence</small></button><button class="card" data-modal="shopping"><strong>🛒 Course</strong><small class="muted">Article partagé</small></button><button class="card" data-modal="expense"><strong>💰 Dépense</strong><small class="muted">Qui paie quoi ?</small></button></div>`)}
function eventForm(e={},date=todayISO()){const cats=state.settings.icons.map(x=>`<option value="${esc(x[1])}" ${e.category===x[1]?'selected':''}>${x[0]} ${esc(x[1])}</option>`).join('');const icons=state.settings.icons.map(x=>`<button type="button" class="icon-option ${e.icon===x[0]?'selected':''}" data-icon="${x[0]}">${x[0]}</button>`).join('');showModal(e.id?'Modifier le rendez-vous':'Nouveau rendez-vous',`<form id="event-form"><div class="form-grid"><div class="field full"><label>Qui ?</label><div class="segmented"><label><input name="owner" type="radio" value="me" ${(!e.owner||e.owner==='me')?'checked':''}><span class="me">🩷 ${esc(state.profile.me)}</span></label><label><input name="owner" type="radio" value="him" ${e.owner==='him'?'checked':''}><span class="him">🩵 ${esc(state.profile.him)}</span></label><label><input name="owner" type="radio" value="both" ${e.owner==='both'?'checked':''}><span class="both">🌿 Nous deux</span></label></div></div><div class="field full"><label>Libellé *</label><input class="input" name="title" required value="${esc(e.title||'')}" placeholder="Ex. Dentiste"></div><div class="field"><label>Date de début *</label><input class="input" name="date" type="date" required value="${e.date||date}"></div><div class="field"><label>Heure de début * (5 min)</label><input class="input" name="time" type="time" step="300" required value="${e.time||'10:00'}"></div><div class="field"><label>Date de fin *</label><input class="input" name="endDate" type="date" required value="${e.endDate||e.date||date}"></div><div class="field"><label>Heure de fin * (5 min)</label><input class="input" name="endTime" type="time" step="300" required value="${e.endTime||'11:00'}"></div><div class="field"><label>Catégorie</label><select class="select" name="category">${cats}</select></div><div class="field"><label>Adresse (optionnel)</label><input class="input" name="address" value="${esc(e.address||'')}" placeholder="12 rue de la Paix, Caen"></div><div class="field full"><label>Informations complémentaires</label><textarea class="textarea" name="notes" placeholder="Pense-bête, document à prendre…">${esc(e.notes||'')}</textarea></div><div class="field full"><label>Icône</label><div class="icon-picker">${icons}</div><input type="hidden" name="icon" value="${esc(e.icon||state.settings.icons[0][0])}"></div><div class="field full"><label><input type="checkbox" name="recurring" ${e.recurring?'checked':''}> 🔁 Rendez-vous récurrent</label></div></div><div class="modal-actions">${e.id?'<button type="button" class="btn danger" data-delete-event="'+e.id+'">Supprimer</button>':''}<button class="btn primary">${e.id?'Enregistrer':'Ajouter'}</button></div></form>`);document.querySelectorAll('[data-icon]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('[name=icon]').value=b.dataset.icon;document.querySelectorAll('[data-icon]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')}));document.getElementById('event-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);const start=f.get('date'),end=f.get('endDate');if(end<start)return toast('La date de fin doit être après la date de début.');if(end===start&&f.get('endTime')<=f.get('time'))return toast("L'heure de fin doit être après l'heure de début.");const item={id:e.id||uid(),owner:f.get('owner'),title:f.get('title').trim(),date:start,time:f.get('time'),endDate:end,endTime:f.get('endTime'),category:f.get('category'),address:f.get('address').trim(),notes:f.get('notes').trim(),icon:f.get('icon'),recurring:f.get('recurring')==='on'};if(e.id)state.events=state.events.map(x=>x.id===e.id?item:x);else state.events.push(item);if(item.recurring&&!e.id)createRecurring('event',item);save();closeModal();toast('Rendez-vous enregistré ❤️')};}
function spawnNextTask(t){if(!t.repeat||t.repeat==='none')return;let next=t.date;if(t.repeat==='daily')next=addDays(t.date,1);else if(t.repeat==='weekly')next=addDays(t.date,7);else if(t.repeat==='monthly'){const d=parseDate(t.date);d.setMonth(d.getMonth()+1);next=localDate(d)}if(!state.tasks.some(x=>x.title===t.title&&x.date===next&&x.owner===t.owner&&!x.done))state.tasks.push({...t,id:uid(),date:next,done:false})}
function createRecurring(type,item){if(type!=='event')return;for(let i=1;i<=12;i++){state.events.push({...item,id:uid(),date:addDays(item.date,7*i),endDate:item.endDate?addDays(item.endDate,7*i):item.endDate})}}
function menuForm(m={},date=todayISO()){showModal(m.id?'Modifier le menu':'Nouveau menu',`<form id="menu-form"><div class="form-grid"><div class="field full"><label>Moment</label><div class="segmented"><label><input name="meal" value="matin" type="radio" ${m.meal==='matin'?'checked':''}><span>☀️ Matin</span></label><label><input name="meal" value="midi" type="radio" ${m.meal==='midi'?'checked':''}><span>☀️ Midi</span></label><label><input name="meal" value="soir" type="radio" ${(!m.meal||m.meal==='soir')?'checked':''}><span>🌙 Soir</span></label></div></div><div class="field"><label>Date *</label><input class="input" name="date" type="date" required value="${m.date||date}"></div><div class="field"><label>Titre *</label><input class="input" name="title" required value="${esc(m.title||'')}" placeholder="Ex. Pâtes bolo"></div><div class="field full"><label>Recette / notes / lien</label><textarea class="textarea" name="description" placeholder="Colle ici le lien de la recette ou tes notes…">${esc(m.description||'')}</textarea></div><div class="field full"><label>Lien cliquable (optionnel)</label><input class="input" name="link" type="url" value="${esc(m.link||'')}" placeholder="https://…"></div></div><div class="modal-actions">${m.id?'<button type="button" class="btn danger" data-delete-menu="'+m.id+'">Supprimer</button>':''}<button class="btn primary">${m.id?'Enregistrer':'Ajouter'}</button></div></form>`);document.getElementById('menu-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);const item={id:m.id||uid(),date:f.get('date'),meal:f.get('meal'),title:f.get('title').trim(),description:f.get('description').trim(),link:f.get('link').trim()};if(m.id)state.menus=state.menus.map(x=>x.id===m.id?item:x);else state.menus.push(item);save();closeModal();toast('Menu enregistré 🍽️')}}
function taskForm(t={},date=todayISO()){showModal(t.id?'Modifier la tâche':'Nouvelle tâche',`<form id="task-form"><div class="form-grid"><div class="field full"><label>Qui ?</label><select class="select" name="owner"><option value="me" ${t.owner==='me'?'selected':''}>🩷 Moi</option><option value="him" ${t.owner==='him'?'selected':''}>🩵 Thomas</option><option value="both" ${t.owner==='both'?'selected':''}>🌿 Nous deux</option></select></div><div class="field full"><label>Tâche *</label><input class="input" name="title" required value="${esc(t.title||'')}" placeholder="Ex. Sortir les poubelles"></div><div class="field"><label>Date *</label><input class="input" name="date" type="date" required value="${t.date||date}"></div><div class="field"><label>Priorité</label><select class="select" name="priority"><option value="urgent" ${t.priority==='urgent'?'selected':''}>🔴 Urgent</option><option value="important" ${t.priority==='important'?'selected':''}>🟠 Important</option><option value="normal" ${(!t.priority||t.priority==='normal')?'selected':''}>🟢 À faire</option><option value="chill" ${t.priority==='chill'?'selected':''}>⚪ Si tu as le temps</option></select></div><div class="field full"><label>Récurrence</label><select class="select" name="repeat"><option value="none">Aucune</option><option value="daily" ${t.repeat==='daily'?'selected':''}>Tous les jours</option><option value="weekly" ${t.repeat==='weekly'?'selected':''}>Toutes les semaines</option><option value="monthly" ${t.repeat==='monthly'?'selected':''}>Tous les mois</option></select></div></div><div class="modal-actions">${t.id?'<button type="button" class="btn danger" data-delete-task="'+t.id+'">Supprimer</button>':''}<button class="btn primary">${t.id?'Enregistrer':'Ajouter'}</button></div></form>`);document.getElementById('task-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);const item={id:t.id||uid(),owner:f.get('owner'),title:f.get('title').trim(),date:f.get('date'),priority:f.get('priority'),repeat:f.get('repeat'),done:t.done||false};if(t.id)state.tasks=state.tasks.map(x=>x.id===t.id?item:x);else state.tasks.push(item);save();closeModal();toast('Tâche enregistrée ☑️')}}
function shoppingForm(i={}){const cats=['Protéines','Desserts','Légumes','Fruits','Petit-déj','Boissons','Goûter','Fromage','Féculents','Apéro','Maison','Autre'];showModal(i.id?'Modifier l’article':'Ajouter aux courses',`<form id="shop-form"><div class="form-grid"><div class="field full"><label>Article *</label><input class="input" name="name" required value="${esc(i.name||'')}" placeholder="Ex. Lait"></div><div class="field"><label>Catégorie</label><select class="select" name="category">${cats.map(c=>`<option ${i.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Quantité</label><input class="input" name="qty" value="${esc(i.qty||'')}" placeholder="2"></div><div class="field full"><label>Ajouté par</label><select class="select" name="owner"><option value="me" ${i.owner==='me'?'selected':''}>🩷 Moi</option><option value="him" ${i.owner==='him'?'selected':''}>🩵 Thomas</option></select></div><div class="field full"><label><input type="checkbox" name="staple" ${i.staple?'checked':''}> Ajouter à mes articles habituels</label></div></div><div class="modal-actions">${i.id?'<button type="button" class="btn danger" data-delete-shop="'+i.id+'">Supprimer</button>':''}<button class="btn primary">${i.id?'Enregistrer':'Ajouter'}</button></div></form>`);document.getElementById('shop-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);const item={id:i.id||uid(),name:f.get('name').trim(),category:f.get('category'),qty:f.get('qty').trim(),owner:f.get('owner'),staple:f.get('staple')==='on',done:i.done||false,addedAt:i.addedAt||Date.now()};if(i.id)state.shopping.items=state.shopping.items.map(x=>x.id===i.id?item:x);else state.shopping.items.push(item);if(item.staple&&!state.shopping.staples.some(x=>x.name.toLowerCase()===item.name.toLowerCase()))state.shopping.staples.push({id:uid(),name:item.name,category:item.category,qty:item.qty});save();closeModal();toast('Article ajouté 🛒')}}
function expenseForm(){showModal('Nouvelle dépense',`<form id="expense-form"><div class="form-grid"><div class="field full"><label>Libellé *</label><input class="input" name="label" required placeholder="Ex. Courses Carrefour"></div><div class="field"><label>Montant (€) *</label><input class="input" name="amount" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Date</label><input class="input" name="date" type="date" value="${todayISO()}"></div><div class="field"><label>Payé par</label><select class="select" name="payer"><option value="me">🩷 Fanny</option><option value="him">🩵 Thomas</option></select></div><div class="field"><label>Pour qui ?</label><select class="select" name="mode"><option value="both">Nous deux · 50/50</option><option value="me">Fanny uniquement</option><option value="him">Thomas uniquement</option><option value="custom">Répartition personnalisée</option></select></div><div class="field"><label>Part Fanny (€)</label><input class="input" name="meShare" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Part Thomas (€)</label><input class="input" name="himShare" type="number" min="0" step="0.01" value="0"></div></div><div class="notice" style="margin-top:10px">Pour « Nous deux », l'appli partage automatiquement à 50/50. Pour « Répartition personnalisée », indique directement le montant que chacun doit supporter.</div><div class="modal-actions"><button class="btn primary">Ajouter</button></div></form>`);document.getElementById('expense-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);const amount=Number(f.get('amount'));const mode=f.get('mode');const item={id:uid(),label:f.get('label').trim(),amount,date:f.get('date'),payer:f.get('payer'),mode,meShare:Number(f.get('meShare'))||0,himShare:Number(f.get('himShare'))||0};if(mode==='custom'&&Math.abs(item.meShare+item.himShare-amount)>.011)return toast('Les parts personnalisées doivent totaliser le montant.');state.expenses.push(item);save();closeModal();toast('Dépense enregistrée 💰')}}
function reimburseForm(){const b=Math.abs(balance());const from=balance()>0?'him':'me',to=from==='me'?'him':'me';showModal('Remboursement',`<form id="reimburse-form"><div class="notice">${from==='him'?'Thomas':'Fanny'} doit actuellement <strong>${money(b)}</strong> à ${to==='me'?'Fanny':'Thomas'}.</div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Montant (€)</label><input class="input" name="amount" type="number" min="0.01" max="${b.toFixed(2)}" step="0.01" value="${b.toFixed(2)}" required></div><div class="field"><label>Date</label><input class="input" name="date" type="date" value="${todayISO()}"></div><div class="field full"><label>Note</label><input class="input" name="note" placeholder="Ex. virement"></div></div><div class="modal-actions"><button class="btn primary">Valider le remboursement</button></div></form>`);document.getElementById('reimburse-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);const a=Number(f.get('amount'));if(a<=0||a>b)return toast('Montant invalide.');state.reimbursements.push({id:uid(),amount:a,date:f.get('date'),from,to,note:f.get('note').trim()});save();closeModal();toast(a===b?'Remboursement soldé ❤️':'Remboursement enregistré')}}
function categoriesModal(){showModal('Catégories de rendez-vous',`<div class="today-list">${state.settings.icons.map((x,i)=>`<div class="list-item"><span style="font-size:20px">${x[0]}</span><div class="item-main"><strong>${esc(x[1])}</strong></div>${i>0?`<button class="btn small" data-remove-cat="${i}">Suppr.</button>`:''}</div>`).join('')}</div><form id="cat-form" style="margin-top:12px"><div class="form-grid"><div class="field"><label>Nom</label><input class="input" name="name" required placeholder="Ex. Vétérinaire"></div><div class="field"><label>Icône</label><input class="input" name="icon" maxlength="2" value="📌"></div></div><div class="modal-actions"><button class="btn primary">＋ Ajouter</button></div></form>`);document.getElementById('cat-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.settings.icons.push([f.get('icon')||'📌',f.get('name').trim()]);save();categoriesModal()};document.querySelectorAll('[data-remove-cat]').forEach(b=>b.onclick=()=>{state.settings.icons.splice(Number(b.dataset.removeCat),1);save();categoriesModal()})}
function moodsModal(){showModal('Messages motivants',`<div class="notice">Chaque tâche cochée peut déclencher un message aléatoire parmi les moods activés. Tu peux les désactiver ou en ajouter autant que tu veux.</div><div class="today-list" style="margin-top:12px">${['me','him'].map(p=>{const m=state.settings.taskMoods[p];return `<div class="card"><div class="row between"><strong>${p==='me'?'🌸 Fanny':'🪖 Thomas'} · ${esc(m.name)}</strong><label><input type="checkbox" data-mood-toggle="${p}" ${m.enabled?'checked':''}> activé</label></div><div style="margin-top:9px">${m.messages.map((x,i)=>`<div class="row between" style="padding:6px 0;border-bottom:1px dashed var(--line)"><span>${esc(x)}</span><button type="button" class="btn small" data-remove-msg="${p}|${i}">×</button></div>`).join('')}</div><form data-add-msg="${p}" style="margin-top:9px"><div class="row"><input class="input" name="message" required placeholder="Nouveau message…"><button class="btn small">＋</button></div></form></div>`}).join('')}</div>`);document.querySelectorAll('[data-mood-toggle]').forEach(x=>x.onchange=()=>{state.settings.taskMoods[x.dataset.moodToggle].enabled=x.checked;save();moodsModal()});document.querySelectorAll('[data-remove-msg]').forEach(x=>x.onclick=()=>{const [p,i]=x.dataset.removeMsg.split('|');state.settings.taskMoods[p].messages.splice(Number(i),1);save();moodsModal()});document.querySelectorAll('[data-add-msg]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const p=form.dataset.addMsg;const f=new FormData(form);state.settings.taskMoods[p].messages.push(f.get('message').trim());save();moodsModal()})}
function profilesModal(){showModal('Vos profils',`<form id="profiles-form"><div class="form-grid"><div class="field"><label>Ton prénom</label><input class="input" name="me" value="${esc(state.profile.me)}"></div><div class="field"><label>Son prénom</label><input class="input" name="him" value="${esc(state.profile.him)}"></div></div><div class="notice" style="margin-top:12px">Les noms servent aux réglages et aux calculs. Les courses utilisent surtout vos typographies pour rester discrètes.</div><div class="modal-actions"><button class="btn primary">Enregistrer</button></div></form>`);document.getElementById('profiles-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.profile.me=f.get('me').trim()||'Fanny';state.profile.him=f.get('him').trim()||'Thomas';save();closeModal();toast('Profils enregistrés ❤️')}}
function staplesModal(){const staples=state.shopping.staples;showModal('Mes articles habituels',`<div class="notice">Ces articles restent enregistrés même après avoir fait les courses. Sélectionne ceux à remettre dans la liste.</div><div class="today-list" style="margin-top:12px">${staples.map(s=>`<label class="list-item"><input type="checkbox" value="${esc(s.id)}"><div class="item-main"><strong>${esc(s.name)}</strong><small>${esc(s.category)}</small></div></label>`).join('')||'<div class="empty">Aucun article habituel pour le moment.</div>'}</div><div class="modal-actions"><button class="btn primary" id="add-staples">Ajouter à la liste</button></div>`);document.getElementById('add-staples').onclick=()=>{document.querySelectorAll('#modal-root input[type=checkbox]:checked').forEach(c=>{const s=staples.find(x=>x.id===c.value);if(s)state.shopping.items.push({...s,id:uid(),owner:'me',done:false,staple:true,addedAt:Date.now()})});save();closeModal();toast('Articles habituels ajoutés 🛒')}}
function suggestionsModal(){const recent=state.shopping.items.filter(i=>i.done||i.addedAt).reduce((m,i)=>{const k=i.name.toLowerCase();(m[k]??=[]).push(i.addedAt||Date.now());return m},{});const candidates=Object.entries(recent).map(([name,dates])=>({name,count:dates.length,last:Math.max(...dates)})).filter(x=>x.count>=2).sort((a,b)=>b.count-a.count).slice(0,10);showModal('Suggestions intelligentes',`<div class="notice">L'appli observe simplement vos achats passés et propose les articles vus régulièrement. Elle n'ajoute jamais un article toute seule.</div><div class="today-list" style="margin-top:12px">${candidates.map(x=>`<label class="list-item"><input type="checkbox" value="${esc(x.name)}"><div class="item-main"><strong>${esc(x.name)}</strong><small>${x.count} achats enregistrés</small></div></label>`).join('')||'<div class="empty">Pas encore assez d’historique. Utilisez la liste quelques semaines et les suggestions apparaîtront ici.</div>'}</div><div class="modal-actions"><button class="btn primary" id="add-suggestions">Ajouter à la liste</button></div>`);document.getElementById('add-suggestions').onclick=()=>{document.querySelectorAll('#modal-root input[type=checkbox]:checked').forEach(c=>{const found=state.shopping.items.find(i=>i.name.toLowerCase()===c.value);state.shopping.items.push({id:uid(),name:found?.name||c.value,category:found?.category||'Autre',qty:found?.qty||'',owner:'me',done:false,addedAt:Date.now()})});save();closeModal();toast('Suggestions ajoutées 🛒')}}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`les-damours-sauvegarde-${todayISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Sauvegarde exportée ❤️')}
function importData(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=()=>{const f=input.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!x.events||!x.menus||!x.tasks)throw new Error();state=x;weekStart=state.weekStart||startWeek(todayISO());save();toast('Sauvegarde restaurée ❤️')}catch{toast('Fichier de sauvegarde invalide.')}};r.readAsText(f)};input.click()}
function switchView(v){currentView=v;renderAll();window.scrollTo({top:0,behavior:'smooth'})}
function bind(){document.addEventListener('click',e=>{const t=e.target.closest('[data-view],[data-action],[data-modal],[data-edit-event],[data-edit-menu],[data-edit-task],[data-edit-shop],[data-toggle-task],[data-toggle-shop],[data-add-date],[data-delete-event],[data-delete-menu],[data-delete-task],[data-delete-shop],[data-taskfilter],[data-shopfilter],[data-weekfilter],[data-birthday-edit]');if(!t)return;if(t.matches('[data-view]')){switchView(t.dataset.view);return}if(t.matches('[data-action]')){const a=t.dataset.action;if(a==='today'){weekStart=startWeek(todayISO());switchView('home')}else if(a==='week')switchView('week');else if(a==='prev-week'){weekStart=addDays(weekStart,-7);saveLocal();renderWeek();switchView('week')}else if(a==='next-week'){weekStart=addDays(weekStart,7);saveLocal();renderWeek();switchView('week')}else if(a==='add')addModal();else if(a==='add-task')taskForm();else if(a==='add-shopping')shoppingForm();else if(a==='add-expense')expenseForm();else if(a==='reimburse')reimburseForm();else if(a==='settings')switchView('settings');else if(a==='profiles')profilesModal();else if(a==='categories')categoriesModal();else if(a==='moods')moodsModal();else if(a==='birthdays')birthdaysModal();else if(a==='staples')staplesModal();else if(a==='suggestions')suggestionsModal();else if(a==='export')exportData();else if(a==='import')importData();else if(a==='auth')authModal();else if(a==='household')householdModal();return}if(t.matches('[data-modal]')){const a=t.dataset.modal;closeModal();setTimeout(()=>a==='event'?eventForm({},t.dataset.addDate||weekStart):a==='menu'?menuForm({},t.dataset.addDate||weekStart):a==='task'?taskForm({},todayISO()):a==='shopping'?shoppingForm():expenseForm(),0);return}if(t.matches('[data-add-date]')){addModal(t.dataset.addDate);return}if(t.matches('[data-birthday-edit]')){const b=state.birthdays.find(v=>v.id===t.dataset.birthdayEdit);if(b){showModal('Modifier un anniversaire','<form id="birthday-edit-form"><div class="form-grid"><div class="field"><label>Prénom / nom *</label><input class="input" name="name" required value="'+esc(b.name)+'"></div><div class="field"><label>Date *</label><input class="input" name="date" type="date" required value="'+esc(b.date)+'"></div></div><div class="modal-actions"><button type="button" class="btn danger" id="delete-birthday">Supprimer</button><button class="btn primary">Enregistrer</button></div></form>');document.getElementById('delete-birthday').onclick=()=>{state.birthdays=state.birthdays.filter(x=>x.id!==b.id);save();closeModal();toast('Anniversaire supprimé')};document.getElementById('birthday-edit-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);b.name=f.get('name').trim();b.date=f.get('date');save();closeModal();toast('Anniversaire modifié 🎂')}}return}if(t.matches('[data-edit-event]')){const x=state.events.find(v=>v.id===t.dataset.editEvent);if(x)eventForm(x);return}if(t.matches('[data-edit-menu]')){const x=state.menus.find(v=>v.id===t.dataset.editMenu);if(x)menuForm(x);return}if(t.matches('[data-edit-task]')){const x=state.tasks.find(v=>v.id===t.dataset.editTask);if(x)taskForm(x);return}if(t.matches('[data-edit-shop]')){const x=state.shopping.items.find(v=>v.id===t.dataset.editShop);if(x)shoppingForm(x);return}if(t.matches('[data-toggle-task]')){const x=state.tasks.find(v=>v.id===t.dataset.toggleTask);if(x){x.done=!x.done;if(x.done){celebrate(x.owner==='him'?'him':'me');spawnNextTask(x)}save()}return}if(t.matches('[data-toggle-shop]')){const x=state.shopping.items.find(v=>v.id===t.dataset.toggleShop);if(x){x.done=!x.done;save()}return}if(t.matches('[data-delete-event]')){state.events=state.events.filter(v=>v.id!==t.dataset.deleteEvent);save();closeModal();toast('Rendez-vous supprimé');return}if(t.matches('[data-delete-menu]')){state.menus=state.menus.filter(v=>v.id!==t.dataset.deleteMenu);save();closeModal();toast('Menu supprimé');return}if(t.matches('[data-delete-task]')){state.tasks=state.tasks.filter(v=>v.id!==t.dataset.deleteTask);save();closeModal();toast('Tâche supprimée');return}if(t.matches('[data-delete-shop]')){state.shopping.items=state.shopping.items.filter(v=>v.id!==t.dataset.deleteShop);save();closeModal();toast('Article supprimé');return}if(t.matches('[data-taskfilter]')){taskFilter=t.dataset.taskfilter;renderTasks();return}if(t.matches('[data-shopfilter]')){shopFilter=t.dataset.shopfilter;renderShopping();return}if(t.matches('[data-weekfilter]')){document.querySelectorAll('[data-weekfilter]').forEach(x=>x.classList.remove('active'));t.classList.add('active');const f=t.dataset.weekfilter;document.querySelectorAll('.event-card').forEach(x=>{if(f==='all')x.style.display='';else if(f==='menu')x.style.display=x.classList.contains('menu')?'':'none';else x.style.display=x.classList.contains(f)?'':'none'});return}});document.addEventListener('click',e=>{if(e.target.matches('[data-close-modal]'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()})}
async function householdModal(){if(!sb||!sync.authUser)return toast('Connecte-toi d’abord.');showModal('Foyer partagé',`<div class="notice">Un seul foyer pour vous deux. Le code ne sert qu’à relier le deuxième compte au même planning.</div><div class="summary-grid" style="margin-top:12px"><button class="card" id="create-household"><strong>❤️ Créer notre foyer</strong><small class="muted">À faire sur le premier téléphone</small></button><button class="card" id="join-household"><strong>🔗 Rejoindre</strong><small class="muted">Avec le code donné par l’autre téléphone</small></button></div>`);document.getElementById('create-household').onclick=async()=>{const {data,error}=await sb.rpc('create_household');if(error)return toast(error.message);sync.household={id:data[0].id,code:data[0].code};await pushState();sync.connected=true;await syncInit();closeModal();renderAll();toast(`Foyer créé · code ${data[0].code}`)};document.getElementById('join-household').onclick=()=>{showModal('Rejoindre votre foyer',`<form id="join-form"><div class="field"><label>Code du foyer</label><input class="input" name="code" required maxlength=8 placeholder="AB12CD34" style="text-transform:uppercase"></div><div class="modal-actions"><button class="btn primary">Rejoindre</button></div></form>`);document.getElementById('join-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const {data,error}=await sb.rpc('join_household',{join_code:f.get('code').trim().toUpperCase()});if(error)return toast(error.message);sync.household={id:data[0].id,code:data[0].code};const {data:r}=await sb.from('household_state').select('state').eq('household_id',sync.household.id).maybeSingle();if(r?.state)state={...defaultState(),...r.state};saveLocal();sync.connected=true;await syncInit();closeModal();renderAll();toast('Vous êtes dans le même foyer ❤️')}}}async function authModal(){if(!sb)return toast('Supabase n’est pas configuré.');showModal(sync.authUser?'Compte connecté':'Connexion',sync.authUser?`<div class="notice">Connecté avec <strong>${esc(sync.authUser.email||'compte')}</strong>.</div><div class="modal-actions"><button class="btn danger" id="signout">Se déconnecter</button></div>`:`<form id="auth-form"><div class="field"><label>Email</label><input class="input" name="email" type="email" required></div><div class="field" style="margin-top:10px"><label>Mot de passe</label><input class="input" name="password" type="password" minlength="6" required></div><div class="modal-actions"><button class="btn" name="mode" value="signin">Se connecter</button><button class="btn primary" name="mode" value="signup">Créer mon compte</button></div></form>`);if(sync.authUser){document.getElementById('signout').onclick=async()=>{await sb.auth.signOut();sync.authUser=null;sync.connected=false;closeModal();renderAll()}}else document.getElementById('auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const {data,error}=await (e.submitter.value==='signup'?sb.auth.signUp({email:f.get('email'),password:f.get('password')}):sb.auth.signInWithPassword({email:f.get('email'),password:f.get('password')}));if(error)return toast(error.message);sync.authUser=data.user;toast('Connexion réussie');closeModal();await syncInit()}}
let syncTimer=null;function queueSync(){if(!sb||!sync.authUser||!sync.household)return;clearTimeout(syncTimer);syncTimer=setTimeout(pushState,500)}
async function pushState(){if(!sb||!sync.authUser||!sync.household)return;const payload={household_id:sync.household.id,state};const {error}=await sb.from('household_state').upsert(payload,{onConflict:'household_id'});if(error)console.warn(error)}
async function syncInit(){if(!sb)return;const {data:{user}}=await sb.auth.getUser();sync.authUser=user;if(!user)return;const {data:m}=await sb.from('household_members').select('household_id,households(id,code)').eq('user_id',user.id).maybeSingle();if(m?.households){sync.household=m.households;const {data:r}=await sb.from('household_state').select('state').eq('household_id',m.household_id).maybeSingle();if(r?.state){state={...defaultState(),...r.state};weekStart=state.weekStart||startWeek(todayISO());saveLocal()}else await pushState();sync.connected=true;renderAll();if(sync.channel)sb.removeChannel(sync.channel);sync.channel=sb.channel(`household-${m.household_id}`).on('postgres_changes',{event:'*',schema:'public',table:'household_state',filter:`household_id=eq.${m.household_id}`},p=>{if(p.new?.state){state={...defaultState(),...p.new.state};weekStart=state.weekStart||startWeek(todayISO());saveLocal();renderAll()}}).subscribe()}}
if(sb){sb.auth.onAuthStateChange((_e,s)=>{sync.authUser=s?.user||null;if(s?.user)setTimeout(syncInit,0);else{sync.connected=false;renderAll()}});setTimeout(syncInit,200)}
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
bind();renderAll();

function birthdaysModal(){
  const list=state.birthdays.map(b=>'<div class="list-item"><span style="font-size:20px">🎂</span><div class="item-main"><strong>'+esc(b.name)+'</strong><small>'+esc(birthdayDateLabel(b))+'</small></div><button class="btn small" data-birthday-edit="'+b.id+'">Modifier</button></div>').join('')||'<div class="empty">Aucun anniversaire pour le moment 🎂</div>';
  showModal('Anniversaires','<div class="notice">Ajoute les anniversaires une seule fois : ils réapparaîtront automatiquement chaque année dans votre semaine et sur la page d’accueil.</div><div class="today-list" style="margin-top:12px">'+list+'</div><form id="birthday-form" style="margin-top:14px"><div class="form-grid"><div class="field"><label>Prénom / nom *</label><input class="input" name="name" required placeholder="Ex. Maman"></div><div class="field"><label>Date *</label><input class="input" name="date" type="date" required></div></div><div class="modal-actions"><button class="btn primary">＋ Ajouter</button></div></form>');
  document.getElementById('birthday-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.birthdays.push({id:uid(),name:f.get('name').trim(),date:f.get('date')});save();birthdaysModal();toast('Anniversaire ajouté 🎂')};
}
